Rule.Source:
  import sailpoint.object.Configuration;
  import sailpoint.api.PasswordPolice;
  import org.apache.commons.logging.Log;
  import org.apache.commons.logging.LogFactory;

  Log log = LogFactory.getLog("sailpoint.rule.ADPasswordTooOld");
  if (newIdentity == null) return false;
  
  boolean resetPassword = false;

  // get the IIQ max password age
  // passwordExpirationDays
  Configuration sysConfig = context.getObjectByName(Configuration.class, Configuration.OBJ_NAME);
  if (sysConfig == null) {
    // that's bad
    log.error(Configuration.OBJ_NAME + " was not found!");
    return false;
  }
  
  // entry key="passwordExpirationDays" value="30"
  String pwdExpirationDaysStr = sysConfig.get(PasswordPolice.EXPIRATION_DAYS);
  if (pwdExpirationDaysStr == null) {
    log.warn("No value specified for maximum password age");
    return false;
  }
  
  Long pwdExpirationDays = null;
  try {
    pwdExpirationDays = Long.valueOf(pwdExpirationDaysStr);
    log.debug("pwdExpirationDays: " + pwdExpirationDays);
  } catch (Throwable t) {
    log.warn("Could not convert " + pwdExpirationDaysStr + " to number value", t);
    return false;
  }
  
  // get the adLastPassword date value
  // adPwdLastSet
  Object adPwdLastSetObj = newIdentity.getAttribute("adPwdLastSet");
  log.debug("adPwdLastSetObj: " + adPwdLastSetObj);

  Long adPwdLastSet = null;
  if (adPwdLastSetObj != null && adPwdLastSetObj instanceof Long) {
    adPwdLastSet = (Long)adPwdLastSetObj;
  } else {
    log.debug(adPwdLastSetObj + " is not a Long");
    return false;
  }
  
  // See if it's older, if so return true
  // Find the difference of adPwdLastSetObj and right now
  long now = System.currentTimeMillis();
  long deltaMs = now - adPwdLastSet;
  long maxDelta = 86400000 * pwdExpirationDays;
  if (deltaMs > maxDelta) {
    // it's been too long
    resetPassword = true;
  } else {
    log.debug(deltaMs + " not greater than " + maxDelta);
    log.debug("now: " + now);
    log.debug("adPwdLastSet: " + adPwdLastSet);
  }
  return resetPassword;
